using UnityEngine;
public sealed class DungeonDecorationRuntime:MonoBehaviour {
 public DungeonMapSettings map;public float cellSize=3,ceilingHeight=3;public Transform generatedRoot;int revision=-1;float nextCheck;
 public void Configure(DungeonMapSettings source,float cell,float height){map=source;cellSize=cell;ceilingHeight=height;Rebuild();}
 public void Rebuild(){if(generatedRoot!=null){generatedRoot.gameObject.SetActive(false);if(Application.isPlaying)Destroy(generatedRoot.gameObject);else DestroyImmediate(generatedRoot.gameObject);}var root=new GameObject("Decoración del mapa — sin colisiones");root.transform.SetParent(transform,false);generatedRoot=root.transform;if(map==null||map.decorations==null)return;revision=map.decorations.revision;var catalog=map.decorations.Catalog;var staticObjects=new System.Collections.Generic.List<GameObject>();foreach(var p in DungeonDecorationPlanner.Build(map)){var def=catalog.Find(p.prefabId);var o=Instantiate(def.prefab,generatedRoot);o.name=def.displayName+" ["+p.id+"]";float scale=Mathf.Clamp(cellSize/3,1,1.25f)*p.scale;var dir=DungeonDecorationPlanner.Directions[p.heading];var facing=new Vector3(-dir.x,0,-dir.y);Vector3 pos=new Vector3(p.cell.x*cellSize,0,p.cell.y*cellSize);if(def.mount==DecorationMount.Wall||def.mount==DecorationMount.Room)pos+=new Vector3(dir.x,0,dir.y)*(cellSize*.5f-.08f);else if(def.mount==DecorationMount.Ceiling)pos.y=ceilingHeight-.03f;else if(def.mount==DecorationMount.Floor)pos.y=.02f;else if(def.mount==DecorationMount.Door)pos+=new Vector3(dir.x,0,dir.y)*cellSize*.5f;o.transform.localRotation=Quaternion.LookRotation(facing)*Quaternion.Euler(0,p.yawOffset,0);o.transform.localPosition=pos+o.transform.localRotation*p.localOffset;o.transform.localScale=def.doorwayFrame?new Vector3(cellSize/3,ceilingHeight/3,scale):Vector3.one*scale;foreach(var collider in o.GetComponentsInChildren<Collider>()){collider.enabled=false;if(Application.isPlaying)Destroy(collider);else DestroyImmediate(collider);}foreach(var light in o.GetComponentsInChildren<Light>())light.enabled=false;foreach(var camera in o.GetComponentsInChildren<Camera>())camera.enabled=false;if(o.GetComponentInChildren<DungeonDecorationMotion>()==null)foreach(var mesh in o.GetComponentsInChildren<MeshFilter>())staticObjects.Add(mesh.gameObject);}if(Application.isPlaying&&staticObjects.Count>0)StaticBatchingUtility.Combine(staticObjects.ToArray(),generatedRoot.gameObject);}
 void Update(){if(Time.unscaledTime<nextCheck)return;nextCheck=Time.unscaledTime+.75f;if(map!=null&&map.decorations!=null&&revision!=map.decorations.revision)Rebuild();}
}
